"use strict";
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..'),out=path.join(root,'docs/auditoria-apostilas-2026-10-16/evidencias');
const items=fs.readdirSync(path.join(out,'itens')).map(f=>JSON.parse(fs.readFileSync(path.join(out,'itens',f),'utf8')));
const urls=new Map();
function add(raw,key,type){if(!raw||raw.includes('referencia-privada')||/drive\.google|docs\.google/.test(raw))return;let u;try{u=new URL(raw,'https://www.resibulando.online');}catch{return;}if(!['https:','http:'].includes(u.protocol))return;u.hash='';const str=u.href;if(!urls.has(str))urls.set(str,{url:str,usages:[]});urls.get(str).usages.push({key,type});}
for(const i of items){for(const l of i.external_links)add(l.url,i.key,'link');for(const img of i.static_images.filter(x=>!x.decorative))add(img.src,i.key,'imagem-inline');for(const f of i.dom_simulation?.inserted_figures||[])add(f.src,i.key,'imagem-dom-simulado');if(i.kind==='apostila-html')add('https://www.resibulando.online/apostilas/'+i.key+'/',i.key,'pagina-publica');}
const remoteDir=path.join(out,'branches');
if(fs.existsSync(remoteDir))for(const f of fs.readdirSync(remoteDir)){const i=JSON.parse(fs.readFileSync(path.join(remoteDir,f),'utf8'));for(const url of i.external_urls||[])add(url,i.key,'link-branch');for(const image of i.embedded_images||[])add(image.src,i.key,'imagem-branch');}
const previousPath=path.join(out,'links-http.json'),old=fs.existsSync(previousPath)?JSON.parse(fs.readFileSync(previousPath,'utf8')).results:[],cached=new Map(old.map(r=>[r.url,r]));
const queue=[...urls.values()].filter(r=>!cached.has(r.url)),results=[...urls.values()].filter(r=>cached.has(r.url)).map(r=>({...cached.get(r.url),usages:r.usages}));let next=0;
async function worker(){while(next<queue.length){const i=next++,entry=queue[i];let body,reader;try{const r=await fetch(entry.url,{redirect:'follow',signal:AbortSignal.timeout(12000),headers:{'User-Agent':'LURIA-editorial-link-audit/1.0','Range':'bytes=0-65535'}});let size=0;const chunks=[];if(r.body){reader=r.body.getReader();while(size<65536){const x=await reader.read();if(x.done)break;chunks.push(x.value);size+=x.value.length;}await reader.cancel();}body=Buffer.concat(chunks).subarray(0,65536);const type=r.headers.get('content-type')||'',html=/html/.test(type)?body.toString('utf8'):'';results.push({...entry,status:r.status,ok:r.ok,final_url:r.url,content_type:type,sampled_bytes:body.length,title:html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1].replace(/\s+/g,' ').slice(0,250)||null,image_response:/^image\//.test(type),access_interpretation:r.status===403||r.status===429?'bloqueio/restrição; não equivale a fonte inexistente':r.status===404||r.status===410?'destino não encontrado nesta consulta':r.ok?'resposta HTTP recebida; conteúdo/licença não certificados':'falha HTTP; revisar destino'});}catch(e){results.push({...entry,status:null,ok:false,error:e.name+': '+e.message,access_interpretation:'falha de transporte ou tempo; não prova inexistência'});}if((i+1)%50===0){fs.writeFileSync(path.join(out,'links-checkpoint.json'),JSON.stringify({processed:results.length,total:queue.length},null,2));console.log(results.length+'/'+queue.length);}}}
(async()=>{await Promise.all(Array.from({length:10},worker));results.sort((a,b)=>a.url.localeCompare(b.url));fs.writeFileSync(path.join(out,'links-http.json'),JSON.stringify({checked_at:new Date().toISOString(),method:'GET com amostra até 64KiB, redirecionamento e timeout 12s; não é inspeção visual ou validação de licença',results},null,2)+'\n');console.log(JSON.stringify({total:results.length,ok:results.filter(r=>r.ok).length,not_found:results.filter(r=>r.status===404||r.status===410).length,restricted:results.filter(r=>r.status===403||r.status===429).length,transport_errors:results.filter(r=>r.status===null).length}));})();
